	@Test
	void contextVisibilityRemainsConsistentAcrossSnapshotCommitRollbackAndClose() throws SailException {
		Resource deletedContext = vf.createIRI("urn:context:snapshot");
		Resource remainingContext = vf.createBNode("snapshot-survivor");
		Statement deletedStatement = vf.createStatement(vf.createIRI("urn:subject:snapshot"),
				vf.createIRI("urn:predicate"), vf.createLiteral("deleted"), deletedContext);
		Model baseStatements = new LinkedHashModel();
		baseStatements.add(deletedStatement);
		baseStatements.add(vf.createIRI("urn:subject:remaining"), vf.createIRI("urn:predicate"),
				vf.createLiteral("remaining"), remainingContext);
		ModelSailSource backingSource = new ModelSailSource(baseStatements);
		SailSourceBranch branch = new SailSourceBranch(backingSource);

		try (SailDataset snapshot = branch.dataset(IsolationLevels.SNAPSHOT)) {
			try (SailSink sink = branch.sink(IsolationLevels.NONE)) {
				sink.deprecate(deletedStatement);
				sink.flush();
			}

			try (SailDataset current = branch.dataset(IsolationLevels.NONE)) {
				assertEquals(List.of(remainingContext), contextIDs(current));
			}
			assertEquals(List.of(deletedContext, remainingContext), contextIDs(snapshot));

			try (SailSink rollback = branch.sink(IsolationLevels.NONE)) {
				rollback.approve(vf.createIRI("urn:subject:rolled-back"), vf.createIRI("urn:predicate"),
						vf.createLiteral("rolled back"), deletedContext);
			}

			try (SailDataset afterRollback = branch.dataset(IsolationLevels.NONE)) {
				assertEquals(List.of(remainingContext), contextIDs(afterRollback));
			}
		} finally {
			branch.close();
		}

		assertEquals(1, backingSource.datasetCloseCount.get());
	}

