	private List<Resource> contextIDs(SailDataset dataset) throws SailException {
		List<Resource> result = new ArrayList<>();
		try (CloseableIteration<? extends Resource> contexts = dataset.getContextIDs()) {
			while (contexts.hasNext()) {
				result.add(contexts.next());
			}
		}
		return result;
	}

	private Changeset newChangeset() {
		return new Changeset() {
			@Override
			public void flush() throws SailException {
			}

			@Override
			public Model createEmptyModel() {
				return new LinkedHashModel();
			}
		};
	}

	private static <T> List<T> iterationValues(CloseableIteration<? extends T> iteration) throws SailException {
		List<T> values = new ArrayList<>();
		while (iteration.hasNext()) {
			values.add(iteration.next());
		}
		return values;
	}

	private static class ModelDataset implements SailDataset {
		protected final Model statements;
		private final AtomicInteger closeCount;

		private ModelDataset(Model statements) {
			this(statements, new AtomicInteger());
		}

		private ModelDataset(Model statements, AtomicInteger closeCount) {
			this.statements = statements;
			this.closeCount = closeCount;
		}

		@Override
		public void close() {
			closeCount.incrementAndGet();
		}

		@Override
		public CloseableIteration<? extends Namespace> getNamespaces() {
			return new EmptyIteration<>();
		}

		@Override
		public String getNamespace(String prefix) {
			return null;
		}

		@Override
		public CloseableIteration<? extends Resource> getContextIDs() {
			return new CloseableIteratorIteration<>(statements.contexts().iterator());
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) {
			return new CloseableIteratorIteration<>(statements.filter(subj, pred, obj, contexts).iterator());
		}
	}

	private static final class ReportingModelDataset extends ModelDataset {
		private final List<TripleTerm> triples;

		private ReportingModelDataset(Model statements) {
			this(statements, new TripleTerm[0]);
		}

		private ReportingModelDataset(Model statements, TripleTerm... triples) {
			super(statements);
			this.triples = List.of(triples);
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) {
			return new ReportingStatementIteration(statements.filter(subj, pred, obj, contexts).iterator());
		}

		@Override
		public CloseableIteration<? extends TripleTerm> getTriples(Resource subj, IRI pred, Value obj) {
			return new ReportingTripleIteration(triples.stream()
					.filter(triple -> subj == null || subj.equals(triple.getSubject()))
					.filter(triple -> pred == null || pred.equals(triple.getPredicate()))
					.filter(triple -> obj == null || obj.equals(triple.getObject()))
					.iterator());
		}
	}

